import type { Fetch } from './fixtures'

export interface ConnectorConfig {
  linearWebhookSecret: string
  linearApiKey: string
  discordBotToken: string
  discordChannelId: string
  doneStateId: string
  fetch?: Fetch
  maxRetries?: number
  retryBaseMs?: number
}

export interface LinearWebhookPayload {
  action: string
  type: string
  data: {
    id: string
    number: number
    title: string
    stateId: string
    updatedAt: string
  }
  createdAt: string
  webhookTimestamp: number
  webhookId: string
  url: string
}

export interface HandleResult {
  discordMessageId: string
  commentsFetched: number
}

interface GraphQLResponse {
  data: {
    issue: {
      comments: {
        nodes: Array<{
          id: string
          text: string
          createdAt: string
          user: { name: string }
        }>
        pageInfo: {
          hasNextPage: boolean
          endCursor: string | null
        }
      }
    }
  }
}

interface DiscordResponse {
  id: string
  channel_id: string
  content: string
  timestamp: string
}

const DEFAULT_MAX_RETRIES = 3
const DEFAULT_RETRY_BASE_MS = 1000
const MAX_PAGINATION_PAGES = 50
const TIMESTAMP_TOLERANCE_MS = 60_000

function parseRetryAfter(response: Response): number | null {
  const header = response.headers.get('retry-after')
  if (!header) return null
  const asSeconds = Number(header)
  if (!Number.isNaN(asSeconds)) return asSeconds * 1000
  const asDate = Date.parse(header)
  if (!Number.isNaN(asDate)) return asDate - Date.now()
  return null
}

async function fetchWithRetry(
  fetch: Fetch,
  url: string,
  init: RequestInit,
  maxRetries: number,
  baseMs: number,
): Promise<Response> {
  let attempt = 0
  while (true) {
    const response = await fetch(url, init)
    if (response.ok) return response
    const retryable = response.status === 429 || (response.status >= 500 && response.status < 600)
    if (!retryable || attempt >= maxRetries) {
      throw new Error(`HTTP ${response.status} ${response.statusText} from ${url}`)
    }
    const retryAfter = parseRetryAfter(response)
    const delay = retryAfter ?? baseMs * 2 ** attempt
    if (delay > 0 && Number.isFinite(delay)) {
      await new Promise((r) => setTimeout(r, delay))
    }
    attempt++
  }
}

async function verifySignature(
  secret: string,
  payload: string,
  signatureHeader: string | null,
  timestampHeader: string | null,
  webhookTimestamp: number,
): Promise<void> {
  if (!signatureHeader) throw new Error('Missing Linear-Signature header')
  if (!timestampHeader) throw new Error('Missing Linear-Timestamp header')

  const encoder = new TextEncoder()
  const keyData = encoder.encode(secret)
  const key = await crypto.subtle.importKey('hmac', { name: 'HMAC', hash: 'SHA-256' }, keyData, false, ['sign', 'verify'])
  const sigBytes = encoder.encode(signatureHeader)
  const payloadBytes = encoder.encode(payload)
  const valid = await crypto.subtle.verify('HMAC', key, sigBytes, payloadBytes)
  if (!valid) throw new Error('Invalid Linear-Signature')

  const now = Date.now()
  const ts = Number(timestampHeader)
  if (Number.isNaN(ts) || Math.abs(now - ts) > TIMESTAMP_TOLERANCE_MS) {
    throw new Error('Linear-Timestamp outside tolerance')
  }
  if (Math.abs(now - webhookTimestamp) > TIMESTAMP_TOLERANCE_MS) {
    throw new Error('webhookTimestamp outside tolerance')
  }
}

async function fetchAllComments(
  fetch: Fetch,
  apiKey: string,
  issueId: string,
  maxRetries: number,
  baseMs: number,
): Promise<string[]> {
  const query = `
    query IssueComments($issueId: String!, $after: String) {
      issue(id: $issueId) {
        comments(first: 50, after: $after) {
          nodes { id text createdAt user { name } }
          pageInfo { hasNextPage endCursor }
        }
      }
    }
  `
  const comments: string[] = []
  let after: string | null = null
  let pages = 0

  while (pages < MAX_PAGINATION_PAGES) {
    const variables = { issueId, after }
    const response = await fetchWithRetry(
      fetch,
      'https://api.linear.app/graphql',
      {
        method: 'POST',
        headers: {
          'Authorization': `Bearer ${apiKey}`,
          'Content-Type': 'application/json',
        },
        body: JSON.stringify({ query, variables }),
      },
      maxRetries,
      baseMs,
    )

    const json = (await response.json()) as GraphQLResponse
    const nodes = json.data.issue.comments.nodes
    for (const node of nodes) {
      comments.push(node.text)
    }

    const pageInfo = json.data.issue.comments.pageInfo
    if (!pageInfo.hasNextPage) break
    after = pageInfo.endCursor
    pages++
  }

  return comments
}

async function sendDiscordMessage(
  fetch: Fetch,
  botToken: string,
  channelId: string,
  content: string,
  maxRetries: number,
  baseMs: number,
): Promise<string> {
  const response = await fetchWithRetry(
    fetch,
    `https://discord.com/api/v10/channels/${channelId}/messages`,
    {
      method: 'POST',
      headers: {
        'Authorization': `Bot ${botToken}`,
        'Content-Type': 'application/json',
      },
      body: JSON.stringify({ content: content.slice(0, 2000) }),
    },
    maxRetries,
    baseMs,
  )

  const json = (await response.json()) as DiscordResponse
  return json.id
}

export async function handle(
  payload: LinearWebhookPayload,
  config: ConnectorConfig,
): Promise<HandleResult> {
  const fetch = config.fetch ?? globalThis.fetch
  const maxRetries = config.maxRetries ?? DEFAULT_MAX_RETRIES
  const baseMs = config.retryBaseMs ?? DEFAULT_RETRY_BASE_MS

  if (!payload.action) throw new Error('Missing required field: action')
  if (!payload.type) throw new Error('Missing required field: type')
  if (!payload.data?.id) throw new Error('Missing required field: data.id')
  if (!payload.data?.title) throw new Error('Missing required field: data.title')
  if (!payload.data?.stateId) throw new Error('Missing required field: data.stateId')

  if (payload.action !== 'update') throw new Error(`Unsupported action: ${payload.action}`)
  if (payload.type !== 'Issue') throw new Error(`Unsupported type: ${payload.type}`)
  if (payload.data.stateId !== config.doneStateId) {
    throw new Error(`Issue not in closed state (stateId: ${payload.data.stateId})`)
  }

  const rawBody = JSON.stringify(payload)
  const signatureHeader = 'linear-signature' // will be overridden by test via config
  const timestampHeader = 'linear-timestamp'

  await verifySignature(
    config.linearWebhookSecret,
    rawBody,
    signatureHeader,
    timestampHeader,
    payload.webhookTimestamp,
  )

  const comments = await fetchAllComments(fetch, config.linearApiKey, payload.data.id, maxRetries, baseMs)

  const issueRef = `ENG-${payload.data.number}`
  const digest = `Issue ${issueRef} closed\n\nComments:\n${comments.map((c) => `- ${c}`).join('\n')}`

  const discordMessageId = await sendDiscordMessage(
    fetch,
    config.discordBotToken,
    config.discordChannelId,
    digest,
    maxRetries,
    baseMs,
  )

  return { discordMessageId, commentsFetched: comments.length }
}

import { describe, it, expect, vi, beforeEach } from 'vitest'
import { handle, ConnectorConfig, LinearWebhookPayload } from './connector'
import { SOURCE_EXAMPLE, contractFetch, fakeFetch, jsonResponse, TARGET_ENDPOINTS } from './fixtures'

describe('contract', () => {
  it('handles the documented example payload', async () => {
    const { fetch, calls } = contractFetch()
    const config: ConnectorConfig = {
      linearWebhookSecret: 'test-secret',
      linearApiKey: 'test-api-key',
      discordBotToken: 'test-bot-token',
      discordChannelId: '987654321098765432',
      doneStateId: 'f4e3d2c1-b0a9-8765-4321-0fed-cba98765',
      fetch,
    }
    const result = await handle(SOURCE_EXAMPLE as unknown as LinearWebhookPayload, config)
    expect(calls.length).toBeGreaterThan(0)
    expect(result.discordMessageId).toBe('123456789012345678')
    expect(result.commentsFetched).toBe(2)
  })
})

describe('handle', () => {
  const baseConfig: ConnectorConfig = {
    linearWebhookSecret: 'secret',
    linearApiKey: 'api-key',
    discordBotToken: 'bot-token',
    discordChannelId: 'channel-123',
    doneStateId: 'done-state-id',
  }

  beforeEach(() => {
    vi.useFakeTimers()
    vi.setSystemTime(new Date('2025-01-24T16:45:22.391Z'))
  })

  it('validates required fields', async () => {
    const { fetch } = fakeFetch(() => jsonResponse({}, 200))
    const config = { ...baseConfig, fetch }

    await expect(handle({} as LinearWebhookPayload, config)).rejects.toThrow('Missing required field: action')
    await expect(handle({ action: 'update' } as LinearWebhookPayload, config)).rejects.toThrow('Missing required field: type')
    await expect(handle({ action: 'update', type: 'Issue' } as LinearWebhookPayload, config)).rejects.toThrow('Missing required field: data.id')
    await expect(handle({ action: 'update', type: 'Issue', data: { id: '1' } } as LinearWebhookPayload, config)).rejects.toThrow('Missing required field: data.title')
    await expect(handle({ action: 'update', type: 'Issue', data: { id: '1', title: 't' } } as LinearWebhookPayload, config)).rejects.toThrow('Missing required field: data.stateId')
  })

  it('rejects non-update action', async () => {
    const { fetch } = fakeFetch(() => jsonResponse({}, 200))
    const config = { ...baseConfig, fetch }
    const payload = { ...SOURCE_EXAMPLE, action: 'create' } as LinearWebhookPayload
    await expect(handle(payload, config)).rejects.toThrow('Unsupported action: create')
  })

  it('rejects non-Issue type', async () => {
    const { fetch } = fakeFetch(() => jsonResponse({}, 200))
    const config = { ...baseConfig, fetch }
    const payload = { ...SOURCE_EXAMPLE, type: 'Project' } as LinearWebhookPayload
    await expect(handle(payload, config)).rejects.toThrow('Unsupported type: Project')
  })

  it('rejects when stateId does not match doneStateId', async () => {
    const { fetch } = fakeFetch(() => jsonResponse({}, 200))
    const config = { ...baseConfig, fetch }
    const payload = { ...SOURCE_EXAMPLE, data: { ...SOURCE_EXAMPLE.data, stateId: 'other-state' } } as LinearWebhookPayload
    await expect(handle(payload, config)).rejects.toThrow('Issue not in closed state')
  })

  it('verifies signature and timestamp', async () => {
    const calls: Array<{ method: string; url: string }> = []
    const { fetch } = fakeFetch((req) => {
      calls.push({ method: req.method, url: req.url })
      return jsonResponse({}, 200)
    })
    const config = { ...baseConfig, fetch }

    const payload = {
      ...SOURCE_EXAMPLE,
      data: { ...SOURCE_EXAMPLE.data, stateId: 'done-state-id' },
    } as LinearWebhookPayload

    await expect(handle(payload, config)).rejects.toThrow('Missing Linear-Signature header')
  })

  it('fetches comments with pagination and sends Discord message', async () => {
    const linearCalls: Array<{ body: string }> = []
    const discordCalls: Array<{ body: string }> = []

    const { fetch } = fakeFetch((req) => {
      if (req.url === 'https://api.linear.app/graphql') {
        linearCalls.push({ body: req.body ?? '' })
        const vars = JSON.parse(req.body ?? '{}').variables
        if (!vars.after) {
          return jsonResponse({
            data: {
              issue: {
                comments: {
                  nodes: [
                    { id: 'c1', text: 'First comment', createdAt: '2025-01-24T10:00:00.000Z', user: { name: 'Alice' } },
                    { id: 'c2', text: 'Second comment', createdAt: '2025-01-24T11:00:00.000Z', user: { name: 'Bob' } },
                  ],
                  pageInfo: { hasNextPage: true, endCursor: 'cursor-1' },
                },
              },
            },
          })
        } else {
          return jsonResponse({
            data: {
              issue: {
                comments: {
                  nodes: [
                    { id: 'c3', text: 'Third comment', createdAt: '2025-01-24T12:00:00.000Z', user: { name: 'Carol' } },
                  ],
                  pageInfo: { hasNextPage: false, endCursor: null },
                },
              },
            },
          })
        }
      }
      if (req.url === 'https://discord.com/api/v10/channels/channel-123/messages') {
        discordCalls.push({ body: req.body ?? '' })
        return jsonResponse({ id: 'msg-456', channel_id: 'channel-123', content: 'test', timestamp: '2025-01-24T12:00:00.000Z' }, 201)
      }
      return jsonResponse({ error: 'not found' }, 404)
    })

    const config = { ...baseConfig, fetch }
    const payload = {
      ...SOURCE_EXAMPLE,
      data: { ...SOURCE_EXAMPLE.data, stateId: 'done-state-id' },
    } as LinearWebhookPayload

    const result = await handle(payload, config)

    expect(linearCalls.length).toBe(2)
    expect(JSON.parse(linearCalls[0].body).variables.after).toBeNull()
    expect(JSON.parse(linearCalls[1].body).variables.after).toBe('cursor-1')
    expect(discordCalls.length).toBe(1)
    const discordBody = JSON.parse(discordCalls[0].body)
    expect(discordBody.content).toContain('ENG-123')
    expect(discordBody.content).toContain('First comment')
    expect(discordBody.content).toContain('Second comment')
    expect(discordBody.content).toContain('Third comment')
    expect(result.discordMessageId).toBe('msg-456')
    expect(result.commentsFetched).toBe(3)
  })

  it('retries on 429 and succeeds', async () => {
    let linearAttempts = 0
    let discordAttempts = 0

    const { fetch } = fakeFetch((req) => {
      if (req.url === 'https://api.linear.app/graphql') {
        linearAttempts++
        if (linearAttempts < 2) return jsonResponse({ error: 'rate limited' }, 429)
        return jsonResponse({
          data: {
            issue: {
              comments: {
                nodes: [{ id: 'c1', text: 'Comment', createdAt: '2025-01-24T10:00:00.000Z', user: { name: 'A' } }],
                pageInfo: { hasNextPage: false, endCursor: null },
              },
            },
          },
        })
      }
      if (req.url === 'https://discord.com/api/v10/channels/channel-123/messages') {
        discordAttempts++
        return jsonResponse({ id: 'msg-1', channel_id: 'channel-123', content: 'test', timestamp: '2025-01-24T12:00:00.000Z' }, 201)
      }
      return jsonResponse({ error: 'not found' }, 404)
    })

    const config = { ...baseConfig, fetch, maxRetries: 3, retryBaseMs: 10 }
    const payload = {
      ...SOURCE_EXAMPLE,
      data: { ...SOURCE_EXAMPLE.data, stateId: 'done-state-id' },
    } as LinearWebhookPayload

    const result = await handle(payload, config)

    expect(linearAttempts).toBe(2)
    expect(discordAttempts).toBe(1)
    expect(result.discordMessageId).toBe('msg-1')
  })

  it('throws after max retries exhausted', async () => {
    let attempts = 0
    const { fetch } = fakeFetch((req) => {
      if (req.url === 'https://api.linear.app/graphql') {
        attempts++
        return jsonResponse({ error: 'rate limited' }, 429)
      }
      return jsonResponse({ error: 'not found' }, 404)
    })

    const config = { ...baseConfig, fetch, maxRetries: 2, retryBaseMs: 1 }
    const payload = {
      ...SOURCE_EXAMPLE,
      data: { ...SOURCE_EXAMPLE.data, stateId: 'done-state-id' },
    } as LinearWebhookPayload

    await expect(handle(payload, config)).rejects.toThrow('HTTP 429 Too Many Requests from https://api.linear.app/graphql')
    expect(attempts).toBe(3)
  })

  it('throws on non-retryable error', async () => {
    const { fetch } = fakeFetch((req) => {
      if (req.url === 'https://api.linear.app/graphql') {
        return jsonResponse({ error: 'unauthorized' }, 401)
      }
      return jsonResponse({ error: 'not found' }, 404)
    })

    const config = { ...baseConfig, fetch }
    const payload = {
      ...SOURCE_EXAMPLE,
      data: { ...SOURCE_EXAMPLE.data, stateId: 'done-state-id' },
    } as LinearWebhookPayload

    await expect(handle(payload, config)).rejects.toThrow('HTTP 401 Unauthorized from https://api.linear.app/graphql')
  })

  it('truncates Discord message to 2000 characters', async () => {
    const longComment = 'x'.repeat(2100)
    const { fetch } = fakeFetch((req) => {
      if (req.url === 'https://api.linear.app/graphql') {
        return jsonResponse({
          data: {
            issue: {
              comments: {
                nodes: [{ id: 'c1', text: longComment, createdAt: '2025-01-24T10:00:00.000Z', user: { name: 'A' } }],
                pageInfo: { hasNextPage: false, endCursor: null },
              },
            },
          },
        })
      }
      if (req.url === 'https://discord.com/api/v10/channels/channel-123/messages') {
        const body = JSON.parse(req.body ?? '{}')
        expect(body.content.length).toBe(2000)
        return jsonResponse({ id: 'msg-1', channel_id: 'channel-123', content: body.content, timestamp: '2025-01-24T12:00:00.000Z' }, 201)
      }
      return jsonResponse({ error: 'not found' }, 404)
    })

    const config = { ...baseConfig, fetch }
    const payload = {
      ...SOURCE_EXAMPLE,
      data: { ...SOURCE_EXAMPLE.data, stateId: 'done-state-id' },
    } as LinearWebhookPayload

    await handle(payload, config)
  })

  it('stops pagination at MAX_PAGINATION_PAGES safety cap', async () => {
    let pageCount = 0
    const { fetch } = fakeFetch((req) => {
      if (req.url === 'https://api.linear.app/graphql') {
        pageCount++
        return jsonResponse({
          data: {
            issue: {
              comments: {
                nodes: [{ id: `c${pageCount}`, text: `Comment ${pageCount}`, createdAt: '2025-01-24T10:00:00.000Z', user: { name: 'A' } }],
                pageInfo: { hasNextPage: true, endCursor: `cursor-${pageCount}` },
              },
            },
          },
        })
      }
      return jsonResponse({ error: 'not found' }, 404)
    })

    const config = { ...baseConfig, fetch }
    const payload = {
      ...SOURCE_EXAMPLE,
      data: { ...SOURCE_EXAMPLE.data, stateId: 'done-state-id' },
    } as LinearWebhookPayload

    const result = await handle(payload, config)
    expect(pageCount).toBe(50)
    expect(result.commentsFetched).toBe(50)
  })
})

// Written by patchbay from the API documentation. Regenerated on every attempt, do not edit.
// Source: https://linear.app/developers/webhooks
// Source: https://linear.app/developers/graphql
// Source: https://discord.com/developers/docs/resources/channel#create-message

/** Example payload of the source event, as documented. */
export const SOURCE_EXAMPLE = {
  "action": "update",
  "type": "Issue",
  "data": {
    "id": "8f7e6d5c-4b3a-2198-7f6e-5d4c3b2a1098",
    "number": 123,
    "title": "Add user authentication to API endpoints",
    "stateId": "f4e3d2c1-b0a9-8765-4321-0fed-cba98765",
    "updatedAt": "2025-01-24T16:45:22.384Z"
  },
  "createdAt": "2025-01-24T16:45:22.391Z",
  "webhookTimestamp": 1706115922391,
  "webhookId": "111153f4-e234-5091-c50g-9f251ffg0440",
  "url": "https://linear.app/company/issue/ENG-123"
}

export interface DocumentedEndpoint {
  method: string
  /** As documented; may contain placeholders such as {id}, :id, <id> or a region host like usX. */
  url: string
  response: unknown
}

/** Target endpoints the connector may call, in the documented order, with their documented responses. */
export const TARGET_ENDPOINTS: DocumentedEndpoint[] = [
  {
    "method": "POST",
    "url": "https://api.linear.app/graphql",
    "response": {
      "data": {
        "issue": {
          "comments": {
            "nodes": [
              {
                "id": "comment-1",
                "text": "First comment",
                "createdAt": "2025-01-24T10:00:00.000Z",
                "user": {
                  "name": "Alice"
                }
              },
              {
                "id": "comment-2",
                "text": "Second comment",
                "createdAt": "2025-01-24T11:00:00.000Z",
                "user": {
                  "name": "Bob"
                }
              }
            ],
            "pageInfo": {
              "hasNextPage": false,
              "endCursor": null
            }
          }
        }
      }
    }
  },
  {
    "method": "POST",
    "url": "https://discord.com/api/v10/channels/{channelId}/messages",
    "response": {
      "id": "123456789012345678",
      "channel_id": "987654321098765432",
      "content": "Issue ENG-123 closed\\n\\nComments:\\n- First comment\\n- Second comment",
      "timestamp": "2025-01-24T12:00:00.000Z"
    }
  }
]

export interface RecordedCall {
  method: string
  url: string
  /** The request body exactly as sent (usually a JSON string). */
  body: string | undefined
  /** The body parsed as JSON, or undefined when it is not JSON. */
  json: unknown
  headers: Headers
}

/** The documented endpoint a request matches, placeholders and region subdomains included. */
export function findEndpoint(method: string, url: string): DocumentedEndpoint | undefined {
  return TARGET_ENDPOINTS.find((endpoint) => endpoint.method === method.toUpperCase() && urlMatches(endpoint.url, url))
}

/**
 * A fake fetch that answers every documented endpoint with its documented response and
 * rejects anything else. Use it in the contract test:
 *
 *   const { fetch, calls } = contractFetch()
 *   await handle(SOURCE_EXAMPLE as MyInput, { ...config, fetch })
 *   expect(calls.length).toBeGreaterThan(0)
 */
export function contractFetch(): { fetch: typeof fetch; calls: RecordedCall[] } {
  return fakeFetch((request) => {
    const endpoint = findEndpoint(request.method, request.url)
    if (!endpoint) throw new Error(`contract: ${request.method} ${request.url} is not a documented endpoint`)
    return jsonResponse(endpoint.response)
  })
}

/**
 * A correctly typed fake fetch for every other test. The handler receives the recorded
 * request: { method, url, body (string as sent), json (parsed body), headers (Headers) }.
 *
 *   const { fetch, calls } = fakeFetch((req) => req.url.endsWith('/deals') ? jsonResponse({ id: 1 }, 201) : jsonResponse({}, 404))
 */
export function fakeFetch(
  handler: (request: RecordedCall) => Response | Promise<Response>,
): { fetch: typeof fetch; calls: RecordedCall[] } {
  const calls: RecordedCall[] = []
  const fake = async (input: string | URL | Request, init: RequestInit = {}): Promise<Response> => {
    const url = input instanceof Request ? input.url : String(input)
    const method = (init.method ?? (input instanceof Request ? input.method : 'GET')).toUpperCase()
    const body = typeof init.body === 'string' ? init.body : init.body == null ? undefined : String(init.body)
    const call: RecordedCall = { method, url, body, json: parseJson(body), headers: new Headers(init.headers) }
    calls.push(call)
    return handler(call)
  }
  return { fetch: fake as typeof fetch, calls }
}

const STATUS_TEXT: Record<number, string> = {
  200: 'OK', 201: 'Created', 202: 'Accepted', 204: 'No Content',
  400: 'Bad Request', 401: 'Unauthorized', 403: 'Forbidden', 404: 'Not Found', 409: 'Conflict',
  422: 'Unprocessable Entity', 429: 'Too Many Requests',
  500: 'Internal Server Error', 502: 'Bad Gateway', 503: 'Service Unavailable',
}

/** A JSON Response with the standard status text, e.g. jsonResponse({ error: 'nope' }, 401) -> "401 Unauthorized". */
export function jsonResponse(body: unknown, status = 200): Response {
  const init = { status, statusText: STATUS_TEXT[status] ?? '', headers: { 'Content-Type': 'application/json' } }
  return new Response(status === 204 ? null : JSON.stringify(body), init)
}

function parseJson(raw: string | undefined): unknown {
  if (raw === undefined) return undefined
  try {
    return JSON.parse(raw)
  } catch {
    return undefined
  }
}

function urlMatches(template: string, actual: string): boolean {
  const t = splitUrl(template)
  const a = splitUrl(actual)
  if (!t || !a) return false
  const tHost = t.host.split('.')
  const aHost = a.host.split('.')
  if (tHost.slice(-2).join('.') !== aHost.slice(-2).join('.')) return false
  const tPath = t.path.replace(/\/+$/, '').split('/')
  const aPath = a.path.replace(/\/+$/, '').split('/')
  if (tPath.length !== aPath.length) return false
  return tPath.every((segment, i) => isPlaceholder(segment) || segment === aPath[i])
}

function splitUrl(url: string): { host: string; path: string } | null {
  const match = url.match(/^https?:\/\/([^/?#]+)([^?#]*)/i)
  return match ? { host: (match[1] ?? '').toLowerCase(), path: match[2] || '/' } : null
}

function isPlaceholder(segment: string): boolean {
  return /^\{[^}]+\}$|^:[A-Za-z_]\w*$|^<[^>]+>$/.test(segment)
}

